import java.io.*;
import java.util.*;

public class B {
    static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        long answer = compute(Math.min(R, C), Math.max(R, C));
        out.println(answer);
        out.close();
    }

    static long compute(long a, long b) {
        if (a < 3 && b < 3) return 0;
        if (a == 1) {
            long total = b;
            long r = b % 6;
            if (r != 0) {
                if (r <= 3) total -= r;
                else if (r == 4) total -= 2;
                else if (r == 5) total -= 1;
            }
            return total;
        }
        if (a == 2) {
            if (b == 3 || b == 7) return 2 * (b - 1);
            return 2 * b;
        }
        long total = a * b;
        return (total & 1) == 0 ? total : total - 1;
    }

    static class FS {
        BufferedReader br;
        StringTokenizer st;

        FS() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            for (;;) {
                if (st != null && st.hasMoreTokens()) break;
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int[] NIA(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        long[] NLA(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }

        char[][] grid(int r, int c) {
            char[][] g = new char[r][c];
            for (int i = 0; i < r; i++) {
                String s = next();
                for (int j = 0; j < c; j++) g[i][j] = s.charAt(j);
            }
            return g;
        }
    }
}
